def ensure_all_media_assets():
    """
    Automaticky overi a vytvori vsechny SVG assety v MEDIA_ROOT i STATIC.
    Bezi bezpecne a rychle pri startu aplikace a pri migracich.
    """
    try:
        media_root = Path(settings.MEDIA_ROOT)

        # 1. Profilove ikonky Dungeon Shopu v MEDIA
        icons_dir = media_root / 'esence_items' / 'icons'
        icons_dir.mkdir(parents=True, exist_ok=True)
        for item in ICONS_CATALOG:
            file_path = icons_dir / f"{item['slug']}.svg"
            if not file_path.exists():
                file_path.write_text(item['svg'].strip(), encoding='utf-8')

        # 2. Ikonky achivementu v MEDIA
        ach_media_dir = media_root / 'achievements'
        ach_media_dir.mkdir(parents=True, exist_ok=True)
        for fname, svg_content in ACHIEVEMENTS_SVGS.items():
            fpath = ach_media_dir / fname
            if not fpath.exists():
                fpath.write_text(svg_content.strip(), encoding='utf-8')

        # 3. Ikonky achivementu ve STATIC (fallback)
        try:
            static_dir = Path(settings.BASE_DIR) / 'static' / 'img' / 'achievements'
            static_dir.mkdir(parents=True, exist_ok=True)
            for fname, svg_content in ACHIEVEMENTS_SVGS.items():
                fpath = static_dir / fname
                if not fpath.exists():
                    fpath.write_text(svg_content.strip(), encoding='utf-8')
        except Exception:
            pass
    except Exception:
        pass
